#!/usr/bin/env python3
"""Bundle the canonical API contract into the add-on without packaging the repo."""
import argparse
import ast
import base64
import json
import zlib
from pathlib import Path


def render(encoded):
    lines = '\n'.join('    ' + repr(encoded[start:start + 100]) for start in range(0, len(encoded), 100))
    return (
        '# Generated by tools/build_api_contract.py; edit api-v1.schema.json instead.\n'
        'import base64\nimport json\nimport zlib\n\n'
        'SCHEMA = json.loads(zlib.decompress(base64.b85decode(\n' + lines + '\n)))\n'
        '\nLEGACY_TARGETS = SCHEMA["x-legacyTargets"]\n'
    )


def matches(content, serialized):
    # Deflate output can vary across zlib builds/platforms. Verify the payload
    # and generated wrapper without importing or executing the generated file.
    try:
        tree = ast.parse(content)
        assignment = next(node for node in tree.body if isinstance(node, ast.Assign)
                          and isinstance(node.targets[0], ast.Name) and node.targets[0].id == 'SCHEMA')
        encoded = ast.literal_eval(assignment.value.args[0].args[0].args[0])
        return (content == render(encoded)
                and zlib.decompress(base64.b85decode(encoded)) == serialized)
    except (SyntaxError, ValueError, TypeError, AttributeError, IndexError, StopIteration, zlib.error):
        return False


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='Check without rewriting generated files')
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    schema = json.loads((root / 'api-v1.schema.json').read_text(encoding='utf-8'))
    serialized = json.dumps(schema, separators=(',', ':')).encode()
    target = root / 'plugin/contract.py'
    if args.check:
        if not target.exists() or not matches(target.read_text(encoding='utf-8'), serialized):
            parser.exit(1, 'Generated contract is stale; run python tools/build_api_contract.py\n')
        print('Generated contract matches source.')
    else:
        encoded = base64.b85encode(zlib.compress(serialized)).decode()
        target.write_text(render(encoded), encoding='utf-8', newline='\n')


if __name__ == '__main__':
    main()
